// AutoRecharge used to be commented out here because nothing could charge the saved
// threshold — no customer could put a card on file at all. That gap is now closed by
// the payment-method card below, and `autoRechargeSweep` in worker/billing.ts really
// does charge the saved card, so the feature is rendered — but only to accounts that
// actually have a card, because without one it still does nothing.
import { AutoRecharge } from "@/components/customer/AutoRecharge";
