            }`}
          >
            {t.label}
          </Link>
        ))}
      </div>

      {tab === "profile" && (
        <>
          <div className="card">
            <h2 className="mb-4 font-semibold">Account overview</h2>
            <dl className="grid gap-4 sm:grid-cols-3">
