              </div>
              <div>
                <dt className="text-xs uppercase tracking-wide text-slate-500">Email</dt>
                <dd className="mt-1 text-sm font-medium">
                  {user.emailVerifiedAt ? (
                    <span className="text-emerald-400">Verified</span>
                  ) : (
                    <span className="text-amber-400">Unverified</span>
                  )}
                </dd>
              </div>
              <div>
                <dt className="text-xs uppercase tracking-wide text-slate-500">Wallet balance</dt>
                <dd className="mt-1 text-sm font-medium tabular-nums">${(user.balanceCents / 100).toFixed(2)}</dd>
              </div>
            </dl>
          </div>

          <div className="card">
            <h2 className="mb-4 font-semibold">Profile</h2>
            <ProfileForm name={user.name} email={user.email} />
          </div>

          <div className="card">
            <h2 className="mb-4 font-semibold">Password</h2>
            <PasswordForm />
          </div>

          <div className="card">
            <div className="mb-1 flex items-center justify-between">
              <h2 className="font-semibold">SSH keys</h2>
              <span className="text-xs text-slate-500">
                {sshKeys.length} key{sshKeys.length === 1 ? "" : "s"}
              </span>
            </div>
            <p className="mb-5 text-sm text-slate-400">
              Keys are injected into new servers automatically at deploy time.
            </p>

            {sshKeys.length > 0 && (
              <ul className="mb-6 divide-y divide-white/[0.05] rounded-xl border border-white/[0.06]">
                {sshKeys.map((k) => (
                  <li key={k.id} className="flex items-center justify-between gap-4 px-4 py-3">
                    <div className="min-w-0">
                      <p className="text-sm font-medium">{k.name}</p>
                      <p className="truncate font-mono text-xs text-slate-500">{shortKey(k.publicKey)}</p>
                    </div>
                    <div className="flex shrink-0 items-center gap-3">
                      <span className="hidden text-xs text-slate-500 sm:block">
                        added {timeAgo(k.createdAt)}
                      </span>
                      <DeleteSshKeyButton keyId={k.id} />
                    </div>
                  </li>
                ))}
              </ul>
            )}

            <AddSshKeyForm />
          </div>

          <DangerZone email={user.email} />
        </>
      )}

      {tab === "security" && (
        <>
          <SecuritySettings totpEnabled={user.totpEnabled} tokens={apiTokens} />
          <SignOutOthersButton />
        </>
      )}

      {tab === "integrations" && (
        <>
          <CloudflareIntegration
            connected={cloudflare.connected}
            kind={cloudflare.kind}
            oauthAvailable={cloudflare.oauthAvailable}
            scopeSummary={cloudflare.scopeSummary}
            redirectUri={cfRedirectUri}
          />

          {/* BYOK — the customer's own Anthropic key. Deep-linked from Build with AI
              as /dashboard/settings?tab=integrations#anthropic-key; keep the id stable. */}
          <section id="anthropic-key" className="scroll-mt-24">
            <ClaudeKeyConnect connected={Boolean(user.anthropicKeyEnc)} />
          </section>

          {discord && (
            <DiscordIntegration
              connected={discord.connected}
              username={discord.username}
              oauthAvailable={discord.oauthAvailable}
              redirectUri={discord.redirectUri}
            />
          )}
        </>
      )}

      {tab === "notifications" && (
        <div className="card">
          <h2 className="mb-1 font-semibold">Notifications</h2>
          <p className="mb-5 text-sm text-slate-400">Choose which emails and alerts you receive.</p>
          <NotificationPrefs prefs={prefs} />
        </div>
      )}
    </div>
  );
}

