  // generate`) for real once this branch is reviewed and ready to promote —
  // see lib/discord-bridge.ts, which reads/writes this field via an explicit
  // unchecked cast until then.
  discordThreadId String?
}

model TicketMessage {
  id        String   @id @default(cuid())
  body      String
  isStaff   Boolean  @default(false)
  ticketId  String
  ticket    Ticket   @relation(fields: [ticketId], references: [id], onDelete: Cascade)
  authorId  String
  author    User     @relation(fields: [authorId], references: [id], onDelete: Cascade)
  createdAt DateTime @default(now())

  // Read receipt — staff -> customer visibility ONLY, never the reverse. Stamped
  // by app/dashboard/support/[id]/page.tsx when a customer views a ticket with
  // unread staff messages (isStaff: true, readAt: null). Rendered as a
  // read/delivered indicator on the ADMIN side only (components/admin/*) — the
  // customer UI never shows a receipt, on themselves or on staff messages they
  // just read. Null until read.
  readAt DateTime?

  // Edit window: `editTicketMessage` (lib/actions-support.ts) lets the original
  // author edit within 5 minutes of `createdAt`, enforced server-side. Unlike
  // `readAt` above, this IS shown to both parties — an edit is a transparency
  // signal, not a privacy one. Null until edited.
  editedAt DateTime?

  // One attachment per message (image or a small set of common document types),
  // bytes stored in Postgres exactly like ChatAttachment/lib/chat-attachment.ts —
  // see lib/ticket-attachment.ts for the validator. All four are null together
  // when the message carries no attachment.
  attachmentData Bytes?
  attachmentMime String?
  attachmentName String?
  attachmentSize Int?
}

enum DomainStatus {
  PENDING
  ACTIVE
model Notification {
  id        String    @id @default(cuid())
  title     String
  body      String?
  href      String?
  readAt    DateTime?
  userId    String
  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  createdAt DateTime  @default(now())
}

model Plan {
  id           String        @id @default(cuid())
  slug         String        @unique
  name         String
  cpuCores     Int
  ramMB        Int
  diskGB       Int
model WalletTransaction {
  stripeSessionId       String?  @unique
  // Same role as stripeSessionId but for OFF-SESSION renewal charges, which have
  // no Checkout session. The UNIQUE constraint — not a read-then-write check — is
  // what makes crediting an auto-charge idempotent when a sweep retries.
  stripePaymentIntentId String?  @unique
  id                    String   @id @default(cuid())
  userId                String
  user                  User     @relation(fields: [userId], references: [id])
  amountCents           Int
  description           String
  createdAt             DateTime @default(now())
}

model AuditLog {
  id        String   @id @default(cuid())
  userId    String?
  user      User?    @relation(fields: [userId], references: [id])
  action    String
  detail    String?
  createdAt DateTime @default(now())
}

/// Per-employee (Role.EMPLOYEE) grant of one admin `Area` (lib/rbac.ts). Plain
/// TEXT rather than a native enum for the same reason AuditLog.action and
/// Expense.category are TEXT: the grantable-area list changes independently
/// of any versioned migration, and this schema is managed with `prisma db
/// push`, not `migrate`. Validated against the `Area` union in code
/// (lib/staff-grants.ts), not at the database layer. SUPPORT/BILLING/ADMIN
/// never read this table — their access still comes entirely from
/// AREA_ROLES in lib/rbac.ts; only EMPLOYEE falls through to a lookup here.
model StaffGrant {
  id          String   @id @default(cuid())
  userId      String
  user        User     @relation("StaffGrants", fields: [userId], references: [id], onDelete: Cascade)
  area        String
  createdById String?
  createdAt   DateTime @default(now())

  @@unique([userId, area])
  @@index([userId])
}

/// An ADDITIONAL company mailbox an EMPLOYEE may read/send from, beyond the
/// one they personally own (User.staffMailboxAddress). Holding the
/// companyInbox StaffGrant only gates whether the inbox FEATURE is reachable
/// at all — it says nothing about WHICH mailboxes within it, which is what
/// this table is for. Confirmed live 2026-09-03 companyInbox previously
enum InvoiceStatus {
  OPEN
  PAID
  VOID
  REFUNDED
}

model Invoice {
  id                String             @id @default(cuid())
  number            Int                @unique @default(autoincrement())
  userId            String
  user              User               @relation(fields: [userId], references: [id], onDelete: Cascade)
  amountCents       Int
  taxCents          Int                @default(0)
  // The VAT/GST rate (percent) actually applied to this invoice's net, and the
  // destination country it was charged for. Recorded at creation from the customer's
  // billing country (lib/tax.ts) so the document states the rate and jurisdiction the
  // tax was collected under — required once tax is genuinely charged. 0 / null on a
  // no-tax invoice (unknown country, reverse charge, or a wallet top-up, which is
  // never a taxable sale).
  taxRatePercent    Float              @default(0)
  taxCountry        String?
  status            InvoiceStatus      @default(OPEN)
  // How much of this invoice has already been refunded. Refunds used to be bound
  // to nothing: `refundPayment` took only (userId, amount) and picked its Stripe
  // target as "most recent top-up, any amount" — so refunding a $24 March invoice
  // issued $24 against the customer's $200 July top-up, the invoice stayed PAID,
  // and the next admin refunded it again. Tracking it here lets the action refuse
  // to exceed the original and mark the invoice REFUNDED.
  refundedCents     Int                @default(0)
  description       String
  lineItems         Json // [{ description, qty, unitCents, amountCents }]
  periodStart       DateTime?
  periodEnd         DateTime?
  paidAt            DateTime?
  // Snapshot of the card used to pay this invoice, captured at the PAID transition
  // so the record survives the customer later swapping or removing their card.
  // Nullable + additive: invoices issued before this existed fall back to the
  // user's current card fields at render time.
  paidBrand         String? // card brand snapshot at time paid (e.g. "visa")
  paidLast4         String? // card last4 snapshot at time paid
  createdAt         DateTime           @default(now())
  // Optional KOL/agency partner commission accrued against this invoice. The FK
  // (with its UNIQUE) lives on PartnerCommission, so this back-relation adds no
  // column to the invoices table — additive/safe for `prisma db push`.
  partnerCommission PartnerCommission?
}

// ---- Growth: coupons / promo codes ----
enum CouponKind {
  PERCENT // value = percent 1-100 (discount on order/topup)
  FIXED_CENTS // value = cents off
  CREDIT_CENTS // value = cents of wallet credit granted on redemption
}

enum CouponScope {
  ANY
  TOPUP
  ORDER
}

/// Which product family a coupon may be redeemed against at checkout.
enum CouponServiceKind {
  ANY
  VPS
  GAME
}

model Coupon {
  id             String             @id @default(cuid())
  code           String             @unique
  kind           CouponKind
  value          Int
  scope          CouponScope        @default(ANY)
  // Which product family this coupon may be used on at checkout. ANY = no
  // restriction; VPS / GAME limit it to that kind of order.
  serviceKind    CouponServiceKind  @default(ANY)
  // Restrict to ONE specific plan by slug (e.g. "starter"). Null = any plan
  // within `serviceKind`. This is how "one free month on the Starter VPS" is
  // locked to Starter and cannot be spent on a bigger plan.
  planSlug       String?
  // Cap how many months of the term the coupon may discount. 1 = one month only,
  // so a percentage/free coupon cannot be stretched across a 12-month order to
  // give a year free. Null = the whole term.
  maxTermMonths  Int?
  firstTimeOnly  Boolean            @default(false)
  minAmountCents Int?
  maxRedemptions Int?
  timesRedeemed  Int                @default(0)
  expiresAt      DateTime?
  active         Boolean            @default(true)
  note           String?
  createdAt      DateTime           @default(now())
  redemptions    CouponRedemption[]
}

model CouponRedemption {
  id               String    @id @default(cuid())
  couponId         String
  coupon           Coupon    @relation(fields: [couponId], references: [id], onDelete: Cascade)
  userId           String
  user             User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  amountCents      Int       @default(0)
  context          String    @default("")
  // Hashed claimant IP (sha256 of ip+salt) — enforces "once per person" beyond
  // one-per-account, so a coupon can't be farmed with throwaway signups. Null on
  // legacy rows / when the IP was unavailable; Postgres treats NULLs as distinct
  // so the unique below never collides on them.
  ipHash           String?
  // Reservation lifecycle — the fix for the card/Stripe (up-front-settlement) race,
  // mirroring PromoRedemption below. UNLIKE the promo, a coupon carries a CONFIGURABLE
  // cap (`Coupon.timesRedeemed` / `maxRedemptions`) on top of the two unique slots, so

model ReferralPartner {
  id                String              @id @default(cuid())
  // Optional login account the partner uses to view their portal at
  // /dashboard/partner. A partner may exist purely as an admin-managed record
  // (no login) until they self-serve. SetNull so deleting the user keeps history.
  userId            String?             @unique
  user              User?               @relation("PartnerAccount", fields: [userId], references: [id], onDelete: SetNull)
  name              String
  contactEmail      String?
  code              String              @unique
  // Lifetime commission rate (percent of the NET, pre-tax charge) earned on every
  // qualifying charge by every attached customer.
  commissionRatePct Float               @default(20)
  status            String              @default("ACTIVE") // ACTIVE | PAUSED
  notes             String?
  createdAt         DateTime            @default(now())
  customers         PartnerCustomer[]
  commissions       PartnerCommission[]
}

/// The durable link binding a referred customer to their referring partner for the
/// life of the account. `customerId` is UNIQUE: a customer is attached to exactly
/// ONE partner, permanently — the "lifetime attribution" guarantee.
model PartnerCustomer {
  id         String          @id @default(cuid())
  partnerId  String
  partner    ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  customerId String          @unique
  customer   User            @relation("PartnerAttachment", fields: [customerId], references: [id], onDelete: Cascade)
  attachedAt DateTime        @default(now())
  createdAt  DateTime        @default(now())

  @@index([partnerId])
}

/// One commission entry per qualifying charge. `invoiceId` is UNIQUE — this is the
/// idempotency guard: at most one commission row can ever exist per invoice, so a
/// retried/duplicated accrual (inline hook + background sweep) can never double-pay
/// a partner. `baseCents` and `ratePct` are snapshotted at accrual so the ledger is
/// a durable record independent of later rate changes.
model PartnerCommission {
  id          String          @id @default(cuid())
  partnerId   String
  partner     ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  customerId  String
  customer    User            @relation("PartnerCommissions", fields: [customerId], references: [id], onDelete: Cascade)
  invoiceId   String          @unique
  invoice     Invoice         @relation(fields: [invoiceId], references: [id], onDelete: Cascade)
  // Net (pre-tax) charge the commission was computed on, the frozen rate, and the
  // resulting commission — all snapshotted at accrual.
  baseCents   Int
  ratePct     Float
  amountCents Int
  kind        String          @default("CHARGE") // ORDER | RENEWAL | CHARGE
  status      String          @default("ACCRUED") // ACCRUED | PAID | VOID
  createdAt   DateTime        @default(now())
  paidAt      DateTime?

  @@index([partnerId, status])
  @@index([customerId])
}

// ---- Admin-managed testimonials (real social proof) ----
model Testimonial {
  id          String   @id @default(cuid())
  author      String
  role        String?
  quote       String
  avatarEmoji String?
  rating      Int      @default(5)
model Feedback {
  id        String   @id @default(cuid())
  userId    String?
  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)
  kind      String // BUG | FEATURE
  title     String
  body      String
  url       String? // page the reporter was on
  status    String   @default("NEW") // NEW | PLANNED | IN_PROGRESS | DONE | DECLINED
  adminNote String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

// ---- Visitor analytics (marketing + portal) ----
model Visit {
  id          String   @id @default(cuid())
  ip          String
  path        String
  referrer    String?
  ua          String?
  // Parsed from `ua` at ingest time (lib/ua-parse.ts, ua-parser-js) — kept as
  // plain columns rather than re-parsed on every analytics read, same reasoning
  // as country/city below. deviceType is one of "Desktop"/"Mobile"/"Tablet"/
  // "Smart TV"/"Console"/"Wearable"/"XR" (UAParser has no positive "desktop"
  // signal — it's the fallback when no other type is detected). os/browser are
  // UAParser's own display names ("iOS", "Android", "Windows", "macOS", "Linux",
  // "Chrome", "Safari", "Firefox", "Edge", …) — null when ua was missing/unparseable.
  deviceType  String?
  os          String?
  browser     String?
  kind        String   @default("marketing") // marketing | portal
model Organization {
  id        String       @id @default(cuid())
  name      String
  ownerId   String
  owner     User         @relation("OrgOwner", fields: [ownerId], references: [id], onDelete: Cascade)
  members   Membership[]
  createdAt DateTime     @default(now())
}

model Membership {
  id        String       @id @default(cuid())
  orgId     String
  org       Organization @relation(fields: [orgId], references: [id], onDelete: Cascade)
  userId    String
  user      User         @relation(fields: [userId], references: [id], onDelete: Cascade)
  role      String       @default("MEMBER") // OWNER | ADMIN | MEMBER | BILLING
  areas     Json? // per-member allowed dashboard areas (null = role default); string[] of area keys
  createdAt DateTime     @default(now())

  @@unique([orgId, userId])
}

// ---- Gift / credit codes ----
model GiftCode {
  id           String    @id @default(cuid())
  code         String    @unique
  amountCents  Int
  note         String?
  redeemedById String?
  redeemedBy   User?     @relation(fields: [redeemedById], references: [id], onDelete: SetNull)
  redeemedAt   DateTime?
  createdAt    DateTime  @default(now())
}

// ---- Security: customer API tokens ----
model ApiToken {
  id         String    @id @default(cuid())
  userId     String
  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  name       String
  prefix     String
  tokenHash  String    @unique
  scopes     String[]  @default([])
  lastUsedAt DateTime?
  expiresAt  DateTime?
  revoked    Boolean   @default(false)
  createdAt  DateTime  @default(now())
}

// ---- Live chat (first-party support widget → admin inbox) ----
model ChatConversation {
  id             String        @id @default(cuid())
  userId         String? // set if the visitor is a signed-in customer
  visitorId      String // anonymous client id (cookie/localStorage)
  name           String?
  email          String?
  status         String        @default("OPEN") // OPEN | CLOSED
  assignedToId   String? // staff user id handling it
  unreadForAgent Boolean       @default(true)
  unreadForUser  Boolean       @default(false)
  lastMessageAt  DateTime      @default(now())

