import { notFound } from "next/navigation";
import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, StatusDot, Badge, timeAgo } from "@/components/ui/primitives";
import { ReplyForm, TicketStatusButton } from "@/components/customer/TicketForms";
import { markTicketMessagesRead } from "@/lib/actions-support";
import { MessageAttachment } from "@/components/support/MessageAttachment";
import { EditableMessageBody } from "@/components/support/EditableMessageBody";

export const dynamic = "force-dynamic";

const priorityTone: Record<string, "slate" | "brand" | "amber" | "red"> = {
  LOW: "slate",
  NORMAL: "brand",
  HIGH: "amber",
  URGENT: "red",
};

export default async function TicketPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await requireUser();
  const ticket = await db.ticket.findUnique({
    where: { id },
    include: {
      messages: {
        select: {
          id: true,
          body: true,
          isStaff: true,
          authorId: true,
          createdAt: true,
          editedAt: true,
          attachmentMime: true,
          attachmentName: true,
          attachmentSize: true,
          author: true,
        },
        orderBy: { createdAt: "asc" },
      },
    },
  });
  if (!ticket || (ticket.userId !== user.id && user.role !== "ADMIN")) notFound();

  // Read receipts flow staff -> customer only ("read receipts from customers,
  // but they dont get them from us"): viewing the ticket as its owning customer
  // stamps `readAt` on every unread staff message, but this page never RENDERS
  // any receipt itself — that indicator only ever appears on the admin thread.
  // A no-op for anyone but the ticket's own customer (including an admin
  // viewing here as themselves, not impersonating).
  await markTicketMessagesRead(ticket.id);

  return (
    <div className="space-y-6">
      <PageHeader title={ticket.subject} sub={`Opened ${timeAgo(ticket.createdAt)}`}>
        <Link href="/dashboard/support" className="btn-ghost">
          ← All tickets
        </Link>
        <TicketStatusButton ticketId={ticket.id} status={ticket.status} />
      </PageHeader>

      <div className="flex items-center gap-3">
        <StatusDot status={ticket.status} />
        <Badge tone={priorityTone[ticket.priority] ?? "slate"}>{ticket.priority.toLowerCase()}</Badge>
      </div>

      <div className="space-y-4">
        {ticket.messages.map((m) => (
          <div key={m.id} className={`flex ${m.isStaff ? "justify-start" : "justify-end"}`}>
            <div
              className={`max-w-[85%] rounded-2xl px-4 py-3 sm:max-w-[70%] ${
                m.isStaff
                  ? "glass rounded-tl-sm"
                  : "rounded-tr-sm bg-gradient-to-br from-accent-blue/30 to-brand-500/30 ring-1 ring-brand-500/30"
              }`}
            >
              <div className="mb-1 flex items-baseline justify-between gap-4">
                <span className={`text-xs font-semibold ${m.isStaff ? "text-brand-300" : "text-slate-200"}`}>
                  {m.isStaff ? `${m.author.name} · Nxeon staff` : m.author.name}
                </span>
                <span className="text-[11px] text-slate-500">{timeAgo(m.createdAt)}</span>
              </div>
              <EditableMessageBody
                messageId={m.id}
                initialBody={m.body}
                createdAtIso={m.createdAt.toISOString()}
                editedAtIso={m.editedAt?.toISOString() ?? null}
                canEditPermission={m.authorId === user.id && ticket.status !== "CLOSED"}
                bodyClassName="whitespace-pre-wrap text-sm text-slate-100"
              />
              {m.attachmentMime && m.attachmentName && (
                <MessageAttachment
                  messageId={m.id}
                  mime={m.attachmentMime}
                  name={m.attachmentName}
                  size={m.attachmentSize ?? 0}
                />
              )}
            </div>
          </div>
        ))}
      </div>

      {ticket.status === "CLOSED" ? (
        <div className="card text-center text-sm text-slate-400">
          This ticket is closed. Reopen it above to continue the conversation.
        </div>
      ) : (
        <div className="card">
          <p className="section-label mb-3">Reply</p>
          <ReplyForm ticketId={ticket.id} />
        </div>
      )}
    </div>
  );
}

