export const dynamic = "force-dynamic";

const statusTone: Record<string, "slate" | "brand" | "amber" | "green" | "red"> = {
  NEW: "slate",
  PLANNED: "brand",
  IN_PROGRESS: "amber",
  DONE: "green",
