// customer can't both spend their referral credit on servers AND cash it out
// (the old bug: earnings were counted as separately cashable on top of the wallet).
//
// available = clamp(0, min(walletBalance, totalEarned − PENDING − APPROVED − PAID))

import { db } from "./db";

/** Exact WalletTransaction.description written for the referrer's reward (see
 *  lib/actions-growth.ts). Used to total affiliate earnings from the ledger. */
export const REFERRAL_EARNING_DESCRIPTION = "Referral bonus — you referred a friend";

/** Minimum balance (cents) a customer must have available to request a payout. */
export const MIN_PAYOUT_CENTS = 2500; // $25.00

/** Payout lifecycle statuses (mirrors AffiliatePayout.status). */
export const PAYOUT_STATUSES = ["PENDING", "APPROVED", "PAID", "DECLINED"] as const;
export type PayoutStatus = (typeof PAYOUT_STATUSES)[number];

/**
 * Commission tiers. `perReferralCents` is what the marketing copy advertises a
 * paying referral is worth once you reach `minReferrals` paying referrals — an
 * escalating incentive. (The wallet credit actually paid per referral is governed
 * by the `referral_reward_cents` Setting / REFERRAL_REWARD_CENTS in the growth
 * engine; these tiers are the customer-facing program description.)
 */
export const AFFILIATE_TIERS = [
  { name: "Starter", minReferrals: 0, perReferralCents: 500 },
  { name: "Pro", minReferrals: 5, perReferralCents: 800 },
  { name: "Elite", minReferrals: 15, perReferralCents: 1200 },
] as const;

export type AffiliateTier = (typeof AFFILIATE_TIERS)[number];

/** The tier a customer currently sits in given their paying-referral count. */
export function currentTier(payingReferrals: number): AffiliateTier {
  let tier: AffiliateTier = AFFILIATE_TIERS[0];
  for (const t of AFFILIATE_TIERS) {
    if (payingReferrals >= t.minReferrals) tier = t;
  }
  return tier;
}

/** The next tier up (null if already at the top), for "N more to unlock…" copy. */
export function nextTier(payingReferrals: number): AffiliateTier | null {
  return AFFILIATE_TIERS.find((t) => t.minReferrals > payingReferrals) ?? null;
}

export type AffiliateEarnings = {
  referredCount: number;
  payingCount: number;
  totalEarnedCents: number;
  pendingPayoutCents: number; // PENDING + APPROVED (in-flight, not yet cashed out)
  paidPayoutCents: number; // PAID
  availableCents: number; // totalEarned − (pending + approved + paid)
  tier: AffiliateTier;
  next: AffiliateTier | null;
  canRequestPayout: boolean;
};

/**
 * Compute a customer's affiliate standing: referral counts, lifetime earnings
 * (from the wallet ledger) and how much is still available to cash out after
 * subtracting non-declined payouts.
 */
export async function computeAffiliateEarnings(userId: string): Promise<AffiliateEarnings> {
  const [referredCount, payingCount, earnedAgg, payouts, account] = await Promise.all([
    db.user.count({ where: { referredById: userId } }),
    db.user.count({ where: { referredById: userId, referralRewardedAt: { not: null } } }),
    db.walletTransaction.aggregate({
      _sum: { amountCents: true },
      where: { userId, description: REFERRAL_EARNING_DESCRIPTION },
    }),
    db.affiliatePayout.findMany({
      where: { userId, status: { not: "DECLINED" } },
      select: { amountCents: true, status: true },
    }),
    db.user.findUnique({ where: { id: userId }, select: { balanceCents: true } }),
  ]);

  const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
  const walletBalanceCents = account?.balanceCents ?? 0;
  let pendingPayoutCents = 0;
  let paidPayoutCents = 0;
  for (const p of payouts) {
    if (p.status === "PAID") paidPayoutCents += p.amountCents;
    else pendingPayoutCents += p.amountCents; // PENDING or APPROVED
  }

  // Referral credit already sits in the wallet; a payout debits the wallet. So the
  // cashable amount is the unclaimed referral commission, but never more than the
  // customer actually still holds in their wallet (they may have spent some of it).
  const unclaimedEarnedCents = Math.max(0, totalEarnedCents - pendingPayoutCents - paidPayoutCents);
  const availableCents = Math.max(0, Math.min(walletBalanceCents, unclaimedEarnedCents));

  return {
    referredCount,
    payingCount,
    totalEarnedCents,
    pendingPayoutCents,
    paidPayoutCents,
    availableCents,
    tier: currentTier(payingCount),
    next: nextTier(payingCount),
