  try {
    const h = await headers();
    const { eventId } = await sendMetaConversion({
      eventName: "CompleteRegistration",
      email,
      externalId: user.id,
      clientIp: clientIp(h),
      userAgent: h.get("user-agent") ?? undefined,
      fbc: jar.get("_fbc")?.value || undefined,
      fbp: jar.get("_fbp")?.value || undefined,
      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/register` : undefined,
    });
    signupEventId = eventId;
  } catch {
    /* tracking is best-effort — the account is already created */
  }
  // `?signup=1` is a one-shot marker read (and immediately stripped) by
  // `SignupTracker` on the dashboard so it can fire the browser-side "signup"
  // conversion. `se` carries the SAME event_id the CAPI event above used, so the
  // browser pixel and the server event dedupe to ONE CompleteRegistration (exactly
  // the Purchase pattern) instead of double-counting. Both are tracking hooks only,
  // never a gate on anything, and any unknown query param is ignored by the page.
  // Send the verification link. Best-effort like the welcome mail and it does
  // NOT block the redirect: signing up and looking around stay open, only
  // buying and provisioning wait on the click (lib/email-verification.ts). If
  // this send fails the account is still usable and still resendable from the
  // portal banner — the customer is never stranded on a screen we control.
  try {
    const { sendVerificationEmail } = await import("./email-verification");
    await sendVerificationEmail(user);
  } catch (e) {
    console.error("[register] verification email failed:", e);
  }
  // Queue a SERVER-SIDE Google Ads conversion for this signup, using the gclid we
  // captured on the ad click. Reliable where the browser gtag is not. Best-effort,
  // idempotent (dedupeKey), and a no-op when the account has no gclid or the Ads
  // API creds aren't configured yet. See lib/google-ads.ts.
  try {
    const { recordAdsConversion } = await import("./google-ads");
    await recordAdsConversion({ kind: "signup", userId: user.id, dedupeKey: `signup:${user.id}` });
  } catch {
    /* tracking is best-effort — the account is already created */
  }
  // Honor `next` (e.g. a partner SSO round-trip back to /sso/authorize) exactly
  // like login() does, via the same safeNext allowlist — an unvalidated redirect
  // target here would be an open redirect. Default stays /dashboard. The
  // signup=1&se= tracking marker is appended either way; SignupTracker only reads
  // it on /dashboard, so a non-dashboard `next` (e.g. the SSO flow) simply won't
  // fire the browser pixel this once — the server-side CAPI/Ads events above
  // already recorded the conversion, so nothing is lost, just the extra pixel.
  const next = safeNext(formData.get("next"));
  const dest = next ?? "/dashboard";
  const marker = `signup=1${signupEventId ? `&se=${encodeURIComponent(signupEventId)}` : ""}`;
  redirect(`${dest}${dest.includes("?") ? "&" : "?"}${marker}`);
}

