import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { invoiceBranding } from "@/lib/invoices";
import { renderInvoicePDF, invoicePdfFilename } from "@/lib/invoice-pdf";

// pdfkit relies on Node APIs (streams, fs-backed font metrics), so pin this
// route to the Node.js runtime rather than the Edge runtime.
export const runtime = "nodejs";

/**
 * Streams the invoice as a REAL, server-rendered PDF (see lib/invoice-pdf.ts).
 *
 * This is the download counterpart of the HTML route in `../route.ts`; it mirrors
 * that route's guards EXACTLY — authenticated, and the caller must own the invoice
 * or be an admin — so the PDF is never a way to read another customer's billing.
 */
export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const invoice = await db.invoice.findUnique({
    where: { id },
    include: { user: { select: { name: true, email: true } } },
  });
  if (!invoice) return NextResponse.json({ error: "not found" }, { status: 404 });

  const isOwner = invoice.userId === user.id;
  const isAdmin = user.role === "ADMIN";
  if (!isOwner && !isAdmin) {
    return NextResponse.json({ error: "forbidden" }, { status: 403 });
  }

  const branding = await invoiceBranding();
  const pdf = await renderInvoicePDF(invoice, invoice.user, branding);
  const filename = invoicePdfFilename(invoice.number, branding.numberPrefix);

  // Uint8Array view keeps NextResponse's BodyInit happy across runtimes.
  return new NextResponse(new Uint8Array(pdf), {
    status: 200,
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": `attachment; filename="${filename}"`,
      "Content-Length": String(pdf.length),
      "Cache-Control": "private, no-store",
    },
  });
}

import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { mintSsoCode, isAllowedRedirect } from "@/lib/partner";

/**
 * SSO authorize (OAuth-style, first-party). Kodely sends the user's BROWSER here:
 *   /sso/authorize?client_id=kodely&redirect_uri=<https…>&state=<opaque>
 *
 * - If the visitor isn't signed into Nxeon, we bounce them through /login and back,
 *   so they end up with a real Nxeon session (this is what makes "one account /
 *   one wallet" work — later redirects to /dashboard/* are already authenticated).
 * - Once signed in, we mint a short-lived signed code bound to their Nxeon userId +
 *   client + redirect_uri and 302 back to Kodely with ?code=&state=.
 * - Kodely's BACKEND then exchanges the code at /api/partner/sso/token (API-key) for
 *   the linked identity. First-party, so we auto-approve (no consent screen).
 */
const CLIENT_ID = "kodely";
const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

export async function GET(req: Request) {
  const url = new URL(req.url);
  const clientId = url.searchParams.get("client_id") ?? "";
  const redirectUri = url.searchParams.get("redirect_uri") ?? "";
  const state = url.searchParams.get("state") ?? "";

  if (clientId !== CLIENT_ID) {
    return NextResponse.json({ error: "unknown client_id" }, { status: 400 });
  }
  if (!(await isAllowedRedirect(redirectUri))) {
    // Reject unknown redirect targets outright — never bounce to an unvetted URL.
    return NextResponse.json({ error: "redirect_uri not allowed" }, { status: 400 });
  }

  const user = await currentUser();
  if (!user) {
    // Send them to log in (or register — AuthForms' "Create account" link carries
    // `next` through too), then straight back here to complete the handshake.
    // MUST be a relative path: `next` is validated by lib/safe-next.ts, which
    // accepts only a same-site "/..." path and rejects an absolute URL outright
    // (that's the open-redirect guard) — an absolute `self` here would silently
    // fail that check and strand the user on /dashboard instead of completing
    // the round trip back to Kodely.
    const self = `/sso/authorize?client_id=${encodeURIComponent(clientId)}&redirect_uri=${encodeURIComponent(redirectUri)}&state=${encodeURIComponent(state)}`;
    return NextResponse.redirect(`${APP_URL}/login?next=${encodeURIComponent(self)}`);
  }

  const code = mintSsoCode(user.id, clientId, redirectUri);
  const back = new URL(redirectUri);
  back.searchParams.set("code", code);
  if (state) back.searchParams.set("state", state);
  return NextResponse.redirect(back.toString());
}

