/**
 * Front door to the Nxeon live-chat AGENT.
 *
 * The assistant is a Claude-powered agent (lib/kb-llm.ts) that reasons over the
 * full operator knowledge base and a suite of live tools — account lookups for
 * signed-in customers, plus public tools for plans, platform status, and help
 * search — and answers in its own words. There is NO keyword-retrieval fallback
 * that pastes blog snippets: retrieval only ever SEEDS the agent as context.
 *
 * When the model is genuinely unavailable (no key configured, or an API error)
 * the bot degrades GRACEFULLY to one warm, honest message that offers a human
 * follow-up — it never dumps an article link as "the answer". The failure reason
 * rides back on the result so the orchestrator (lib/kb-run.ts) can log a real
 * degradation for the operator instead of failing silently.
 *
 * Every call returns a typed `kind` so app/api/chat/route.ts can log it.
 * The index (KbChunk) is (re)built by lib/actions-kb.ts → reindexKb().
 */

const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

export type ReplyKind = "smalltalk" | "handoff" | "offer" | "answer" | "degraded";
export type KbResult = {
  kind: ReplyKind;
  reply: string | null;
  matchedTitle?: string;
  /** Plan-card keys to render with this reply (resolved to cards in kb-run). */
  cardKeys?: string[];
  /** Present only when the model was unavailable, so the orchestrator can log a
   *  real degradation and alert the operator on a hard error (never silent). */
  llmFailure?: "no_key" | "error" | "over_cap";
};

/** Warm, honest degradation — used ONLY when the model can't run (no key / API
 *  error / over the daily cap). Never a blog link; offers a human follow-up.
 *  Exported so the graceful-degradation contract (offers contact/pricing, never
 *  a blog link) can be asserted in a hermetic unit test. */
export function degradedReply(reason: "no_key" | "error" | "over_cap", name?: string | null): string {
  const who = name && name.trim() ? ` ${name.trim()}` : "";
  if (reason === "over_cap") {
    return `Thanks${who} — we're helping a lot of people in chat right now, so rather than rush you I want to make sure you get a solid answer. Drop your email with your question and the team will get right back to you (usually within a business day). In the meantime, ${APP_URL}/pricing has every plan and ${APP_URL}/help has quick guides.`;
  }
  return `Sorry${who} — I'm having a brief problem reaching my assistant just now. I don't want to guess at your answer. If you leave your email and what you need, the team will follow up quickly — or you can reach us any time at ${APP_URL}/contact. You can also check live status at ${APP_URL}/status.`;
}

/** "which plan / what plan / recommend a plan / best plan / plan for X". */
export function planIntent(text: string): boolean {
  return /\b(which|what|best)\s+plan\b|\bplan\s+(should|would|do|for|to)\b|\brecommend\s+(a\s+)?plan\b|\bhelp me (choose|pick)\b|\bwhich (one|option|tier)\b/i.test(
    text,
  );
}

type Row = { source: string; title: string; url: string | null; snippet: string; offer: boolean; rank: number };

/** Explicit "get me a person". */
export function humanIntent(text: string): boolean {
  return /\b(human(?:\s+(?:being|agent))?|agent|operator|representative|rep|customer\s+(?:service|support|rep)|real\s+(?:person|human)|actual\s+(?:person|human)|live\s+(?:chat|agent|support|person)|someone|a person|talk to (?:a|your|the|someone)|speak (?:to|with)|connect me|get me (?:a|someone))\b/i.test(text);
}

/** "Do you have any deals / discounts / promos?" */
export function offerIntent(text: string): boolean {
  return /\b(deal|deals|discount|discounts|promo|promotion|coupon|voucher|offer|offers|sale|cheaper|save (money|some)|free month|free trial|any specials?)\b/i.test(text);
}

/** Top knowledge-base matches. websearch_to_tsquery parses arbitrary user input
 *  safely, so this is injection- and crash-safe for anything a visitor types. */
export async function kbSearch(query: string, limit = 4): Promise<Row[]> {
  const q = query.trim();
  if (q.length < 3) return [];
  try {
    return await db.$queryRaw<Row[]>`
      SELECT source, title, url, snippet, "offer",
             ts_rank(to_tsvector('english', title || ' ' || content),
                     websearch_to_tsquery('english', ${q})) AS rank
      FROM "KbChunk"
      WHERE to_tsvector('english', title || ' ' || content) @@ websearch_to_tsquery('english', ${q})
      ORDER BY rank DESC
      LIMIT ${limit}`;
  } catch {
    return [];
  }
}

/**
 * Decide how the assistant should respond to a visitor message. Priority:
 * explicit human hand-off → the Claude agent (tools + full KB, for everyone) →
 * graceful degradation if the model can't run. There is no keyword-retrieval
 * fallback and no canned "clarifier" — the agent handles greetings, questions,
 * and everything in between. Always returns a `kind` so the caller can log
 * coverage. `history` is the prior conversation (oldest→newest) for context.
 */
export async function kbAnswer(message: string, opts: KbAnswerOpts = {}): Promise<KbResult> {
  const history = opts.history ?? [];

  // 1. Explicit "get me a person" — hand-off (kb-run turns this into the live
  //    escalation + email flow). No tokens spent.
  if (humanIntent(message)) {
    return {
      kind: "handoff",
      reply:
        "No problem — I'll connect you with our team. Someone will be with you shortly. Feel free to add any details in the meantime.",
    };
  }

  // 2. Over the daily cost cap → degrade gracefully (no model call, no snippet).
  if (opts.noLlm) {
    return {
      kind: "degraded",
      reply: degradedReply("over_cap", opts.visitorName),
      llmFailure: "over_cap",
    };
  }

  // 3. Seed a little help context (cheap FTS), then run the agent for EVERYONE.
  //    The agent investigates with its tools and answers in its own words; plan
  //    cards ride back via a hidden [[cards: …]] directive parsed in kb-run.
  const rows = await kbSearch(message);
  const chunks = rows.map((r) => ({ title: r.title, snippet: r.snippet, url: r.url }));
  const res = await llmAnswer({
    message,
    history,
    chunks,
    images: opts.images,
    visitorName: opts.visitorName ?? null,
    userId: opts.userId ?? null,
    conversationId: opts.conversationId ?? null,
  });

  if (res.ok) {
    return {
      kind: offerIntent(message) ? "offer" : "answer",
      reply: res.text,
      matchedTitle: rows[0]?.title,
    };
  }

  // 4. Model unavailable. NEVER paste a blog snippet. A plain greeting still gets
  //    a warm hello; anything else gets an honest "let me get the team" message.
  //    The failure reason rides back so kb-run logs a real degradation.
  if (res.reason === "no_key" && greetingIntent(message)) {
    return { kind: "smalltalk", reply: greetingReply(opts.visitorName) };
  }
  return {
    kind: "degraded",
    reply: degradedReply(res.reason === "error" ? "error" : "no_key", opts.visitorName),
    llmFailure: res.reason === "error" ? "error" : "no_key",
  };
}

