/** Set by `components/customer/CouponField`; read by `topUp`'s demo gateway only. */
const COUPON_COOKIE = "nxeon_coupon";

export async function POST(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (!stripeConfigured()) {
    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
  }
  const { amount } = await req.json().catch(() => ({}));
  const dollars = Number(amount);
  if (!Number.isFinite(dollars) || dollars > 5000) {
    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
  }
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (Math.round(dollars * 100) < minTopup) {
    return NextResponse.json(
      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
      { status: 400 },
    );
  }

  // A promo code must never be silently dropped at the moment money moves.
  //
  // `CouponField` stores an accepted code in this cookie for an hour, and the ONLY
  // reader is the demo gateway in `topUp`. This route charges the card and
  // `creditCheckoutSession` credits `session.amount_total` verbatim, so a bonus
  // simply cannot be added here — and Stripe's own `discounts` /
  // `allow_promotion_codes` are the wrong instrument for a wallet top-up: they
  // reduce `amount_total`, which reduces the credit by the same cents, leaving the
  // customer exactly where they started. So a cookie surviving into this path
  // (e.g. Stripe was configured after the code was accepted) would mean paying
  // full price with a code the UI said was applied — the audit's finding #8.
  //
  // Refuse, say why, and clear the cookie in the same response so the immediate
  // retry succeeds. Nothing has been charged at this point: no session exists yet.
  const staleCoupon = req.cookies.get(COUPON_COOKIE)?.value?.trim();
  if (staleCoupon) {
    const shown = staleCoupon.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32).toUpperCase();
    const res = NextResponse.json(
      {
        error: `Promo code ${shown || "on this account"} can’t be applied to a card payment. We’ve removed it — press Add funds again to continue without it.`,
      },
      { status: 400 },
    );
    res.cookies.set({ name: COUPON_COOKIE, value: "", path: "/", maxAge: 0 });
    return res;
  }

  // Custom Checkout (ui_mode: "elements") — the SAME session shape/UI mode the
  // VPS/Hosting/Game/Email deploy wizards' Payment step uses (PaymentStep.tsx),
  // mounted here in AddFundsPaymentModal instead of Stripe's own hosted-style
  // embedded page. `createTopUpPaymentSession` attaches the payment to a Stripe
  // CUSTOMER and saves the card (off-session renewals) exactly as before — see
  // its doc comment in lib/stripe.ts for why the session carries no order/game/
  // host/email metadata key (it must classify as a plain top-up).
  const session = await createTopUpPaymentSession(user, Math.round(dollars * 100));
  return NextResponse.json(
    session ? { clientSecret: session.clientSecret, publishableKey: session.publishableKey } : { error: "Stripe didn't return a session. Please try again." },
    session ? undefined : { status: 502 },
  );
}
