import { NextRequest, NextResponse } from "next/server";
import { stripeConfigured } from "@/lib/stripe";
import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";

/**
 * Checkout success-redirect target.
 *
 * This route no longer OWNS fulfilment — it asks the shared, idempotent
 * `fulfilCheckoutSession` to do it and follows whatever redirect comes back. The
 * webhook calls the identical function, so whichever arrives first fulfils and the
 * other is a harmless no-op.
 *
 * Until 2026-07-25 the logic lived here and was gated on whether the wallet credit
 * was inserted by THIS request — which made a browser redirect the fulfilment
 * trigger. If the webhook won the race, or the customer simply closed the tab
 * before this URL resolved, the payment was captured and nothing was provisioned:
 * no server, no error, no notification. Stripe's own guidance is explicit that a
 * redirect must never be what triggers fulfilment.
 */
export async function GET(req: NextRequest) {
  const base = process.env.APP_URL ?? "";
  const sessionId = req.nextUrl.searchParams.get("session_id");
  if (!stripeConfigured() || !sessionId) {
    return NextResponse.redirect(`${base}/dashboard/billing`);
  }
  try {
    const result = await fulfilCheckoutSession(sessionId, base);
    return NextResponse.redirect(result.redirect);
  } catch {
    // Never strand the customer on an error page: the webhook is an independent
    // backstop and will fulfil this session regardless of what happened here.
    return NextResponse.redirect(`${base}/dashboard/billing?pending=1`);
  }
}

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";

const schema = z.object({
  enabled: z.boolean(),
  threshold: z.coerce.number().min(0).max(10000),
  amount: z.coerce.number().min(0).max(10000),
});

/**
 * Persist wallet auto-recharge preferences for the current user. Dollar inputs
 * are converted to integer cents. When enabled, both a positive threshold and a
 * positive top-up amount are required. This only stores preferences — the actual
 * off-session Stripe charge is wired by the orchestrator.
 */
export async function saveAutoRecharge(
  prev: any,
  formData: FormData
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  const parsed = schema.safeParse({
    enabled: formData.get("enabled") === "on",
    threshold: formData.get("threshold") || 0,
    amount: formData.get("amount") || 0,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid auto-recharge settings." };
  }
  const { enabled, threshold, amount } = parsed.data;

  const thresholdCents = Math.round(threshold * 100);
  const amountCents = Math.round(amount * 100);

  if (enabled) {
    if (amountCents < 500) {
      return { error: "Recharge amount must be at least $5.00 when auto-recharge is on." };
    }
    if (thresholdCents < 0) {
      return { error: "Threshold can't be negative." };
    }
  }

  await db.user.update({
    where: { id: user.id },
    data: {
      autoRechargeEnabled: enabled,
      autoRechargeThresholdCents: enabled ? thresholdCents : null,
      autoRechargeAmountCents: enabled ? amountCents : null,
    },
  });

  revalidatePath("/dashboard/billing");
  return { ok: true };
}

// ---------------- Billing profile: country + VAT id (Finding 1) ----------------

const profileSchema = z.object({
  // ISO-3166 alpha-2, or empty to clear. Uppercased.
  country: z
    .string()
    .trim()
    .transform((s) => s.toUpperCase())
    .refine((s) => s === "" || /^[A-Z]{2}$/.test(s), "Enter a 2-letter country code (e.g. DE, GB)."),
  vatId: z.string().trim().max(20).transform((s) => s.toUpperCase()),
});

/**
 * Save the customer's billing country + VAT id. These DRIVE the VAT/GST actually
 * charged on their orders and renewals (lib/tax.ts): the country is the destination
 * rate, and a valid EU VAT id in a different member state gets the 0% reverse charge.
 * Left blank => no country on file => tax falls back to the global rate (0 by default),
 * so nothing is charged until the customer supplies a country. Empty strings are
 * stored as NULL so `taxContextForUser` treats them as "unknown".
 */
export async function saveBillingProfile(
  prev: any,
  formData: FormData,
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  const parsed = profileSchema.safeParse({
    country: formData.get("country") ?? "",
    vatId: formData.get("vatId") ?? "",
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid billing details." };
  }
  await db.user.update({
    where: { id: user.id },
    data: {
      billingCountry: parsed.data.country || null,
      vatId: parsed.data.vatId || null,
    },
  });
  revalidatePath("/dashboard/billing");
  return { ok: true };
}

