/**
 * Create an organization owned by the current user, plus an OWNER membership
 * for the creator. Consumed via `useActionState`.
 */
export async function createOrg(
  _prev: unknown,
  formData: FormData,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  if (name.length < 2 || name.length > 60) {
    return { error: "Organization name must be 2–60 characters." };
  }

  await db.organization.create({
    data: {
      name,
      ownerId: user.id,
      members: {
        create: { userId: user.id, role: "OWNER" },
      },
    },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "org.created", detail: name },
  });
  revalidatePath("/dashboard/team");
  return { ok: true };
}

/**
 * Email an invitation. Only OWNER/ADMIN of the org may invite. **No Membership
 * is created here** — the invitee creates it themselves via `acceptInvite`.
 *
 * Deliberately does NOT look the email up in the User table. The old version
 * did, and that single query produced two leaks from one action any signed-in
 * customer can call: it answered "does an account exist with this address?"
 * (enumeration oracle), and on a hit it created a Membership whose row then
 * exposed the invitee's internal `userId` on the team page — the input the
 * unauthenticated 2FA oracle needed (QA-PRELAUNCH P0-2). We send the mail and
 * learn nothing: the same response comes back whether or not the address has an
 * account, and the sender finds out only if the person chooses to accept.
 */
export async function inviteMember(
  orgId: string,
  email: string,
  role: string,
): Promise<{ error?: string; ok?: boolean; message?: string }> {
  const user = await requireUser();
  const invitedEmail = String(email ?? "").trim().toLowerCase();
  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
    return { error: "Enter a valid email address." };
  }
  const wantRole = String(role ?? "MEMBER").toUpperCase();
  if (!isRole(wantRole) || wantRole === "OWNER") {
    // OWNER is assigned only at creation / ownership transfer, never via invite.
    return { error: "Choose a role of ADMIN, MEMBER or BILLING." };
 * Takes a `membershipId`, not a `userId`: the client is never sent co-members'
 * user ids any more (see app/dashboard/team/page.tsx), so it has none to send
 * back. The org is derived from the membership rather than trusted from the
 * caller, which also removes the chance of a mismatched (orgId, userId) pair.
 */
export async function updateMemberRole(
  membershipId: string,
  role: string,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const wantRole = String(role ?? "").toUpperCase();
  if (!isRole(wantRole) || wantRole === "OWNER") {
    return { error: "Pick a role of ADMIN, MEMBER or BILLING." };
  }

  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
  if (!target) return { error: "That person isn't a member of this organization." };

  const actor = await actorMembership(target.orgId, user.id);
  if (!actor || !canAdministerOrg(actor.role)) {
    return { error: "You don't have permission to change roles in this organization." };
  }

  const org = await db.organization.findUnique({
    where: { id: target.orgId },
    select: { ownerId: true },
  });
  if (!org) return { error: "Organization not found." };
  if (target.userId === org.ownerId || target.role === "OWNER") {
    return { error: "The organization owner's role can't be changed." };
  }

  await db.membership.update({
    where: { id: target.id },
    data: { role: wantRole },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "org.member_role_changed",
      detail: `${target.userId} → ${wantRole}`,
    },
  });
  revalidatePath("/dashboard/team");
  return { ok: true };
}

/**
 * Remove a member. Only OWNER/ADMIN act; the owner can never be removed.
 * Keyed by `membershipId` for the same reason as `updateMemberRole`.
 */
export async function removeMember(
  membershipId: string,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
  if (!target) return { error: "That person isn't a member of this organization." };

  const actor = await actorMembership(target.orgId, user.id);
  if (!actor || !canAdministerOrg(actor.role)) {
    return { error: "You don't have permission to remove members from this organization." };
  }

  const org = await db.organization.findUnique({
    where: { id: target.orgId },
    select: { ownerId: true },
  });
  if (!org) return { error: "Organization not found." };
  if (target.userId === org.ownerId || target.role === "OWNER") {
    return { error: "The organization owner can't be removed." };
  }

  await db.membership.delete({ where: { id: target.id } });
  await db.auditLog.create({
    data: { userId: user.id, action: "org.member_removed", detail: target.userId },
  });
  revalidatePath("/dashboard/team");
  return { ok: true };
}

/**
 * Leave an organization. The owner can't leave their own org (they'd have to
 * transfer ownership first — a follow-up), everyone else may.
 */
export async function leaveOrg(orgId: string): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
  if (!org) return { error: "Organization not found." };
  if (org.ownerId === user.id) {
    return { error: "As the owner you can't leave — transfer ownership or delete the organization instead." };
  }

  const membership = await actorMembership(orgId, user.id);
  if (!membership) return { error: "You're not a member of this organization." };

  await db.membership.deleteMany({ where: { orgId, userId: user.id } });
  await db.auditLog.create({
    data: { userId: user.id, action: "org.left", detail: orgId },
  });
  revalidatePath("/dashboard/team");
  return { ok: true };
}

